arguments.command:
cd /tmp/orchestra-03/micro2/micro-groups && RAW=docs/changes/tool-cli/verify-5d3765e-r1/acc-g5b-1-raw.txt; {
echo "==============================================================";
echo "PRODUCT VERIFY g5b-1  target HEAD = $(git rev-parse HEAD)";
echo "workdir = $(pwd)";
echo "==============================================================";
echo;
echo "### STEP 1: run prepare.sh";
echo "### CMD: bash prepare.sh";
echo "### START_LOCAL: $(date '+%Y-%m-%d %H:%M:%S %Z')";
echo "### START_UTC:   $(date -u +%Y-%m-%dT%H:%M:%SZ)";
} > "$RAW";
S=$(date +%s.%N);
bash prepare.sh > /tmp/prep_out.txt 2> /tmp/prep_err.txt; RC=$?;
E=$(date +%s.%N);
{
echo "### EXIT_CODE: $RC";
echo "### END_LOCAL:  $(date '+%Y-%m-%d %H:%M:%S %Z')";
echo "### END_UTC:    $(date -u +%Y-%m-%dT%H:%M:%SZ)";
echo "### DURATION_S: $(awk -v s=$S -v e=$E 'BEGIN{printf "%.2f", e-s}')";
echo "### STDOUT (verbatim, $(wc -c < /tmp/prep_out.txt) bytes):";
cat /tmp/prep_out.txt;
echo "### STDERR (verbatim, $(wc -c < /tmp/prep_err.txt) bytes):";
cat /tmp/prep_err.txt;
echo "### END STEP 1";
echo;
} >> "$RAW";
sed -n '1,60p' "$RAW"; echo "=== dist listing ==="; ls -la dist 2>/dev/null || echo "no dist dir"

cd /tmp/orchestra-03/micro2/micro-groups && RAW=docs/changes/tool-cli/verify-5d3765e-r1/acc-g5b-1-raw.txt; APP=dist/app.txt; {
echo "### STEP 2: inspect dist/app.txt (line structure)";
echo "### CMD: wc -c -l dist/app.txt; sed -n '1,3p' dist/app.txt | cat -A; od -c dist/app.txt";
echo "### START_LOCAL: $(date '+%Y-%m-%d %H:%M:%S %Z')";
echo "--- wc -c -l ---";
wc -c -l "$APP"; echo "exit=$?";
echo "--- sed -n '1,3p' | cat -A (shows \$ = line end, no trailing spaces unmarked) ---";
sed -n '1,3p' "$APP" | cat -A; echo "exit=$?";
echo "--- od -c full file ---";
od -c "$APP"; echo "exit=$?";
echo "--- sed -n '4,$p' (anything after line 3?) ---";
sed -n '4,$p' "$APP" | cat -A; echo "count_of_lines_4plus=$(sed -n '4,$p' "$APP" | wc -l)";
echo "### END STEP 2";
echo;
} >> "$RAW"; sed -n '/STEP 2/,$p' "$RAW"

cd /tmp/orchestra-03/micro2/micro-groups && RAW=docs/changes/tool-cli/verify-5d3765e-r1/acc-g5b-1-raw.txt; APP=dist/app.txt
run_ac() {
  local N="$1" EXP="$2" ID="$3"
  {
  echo "### $ID : read line $N of dist/app.txt and compare strictly (bytes incl. newline) with expected literal";
  echo "### CMD: sed -n '${N}p' dist/app.txt";
  echo "### START_LOCAL: $(date '+%Y-%m-%d %H:%M:%S %Z')";
  echo "### START_UTC:   $(date -u +%Y-%m-%dT%H:%M:%SZ)";
  local OUT; OUT=$(sed -n "${N}p" "$APP"); local RC=$?
  echo "### sed exit=$RC";
  echo "### RAW LINE (quoted): >>>${OUT}<<<";
  echo "### RAW LINE (cat -A): $(printf '%s' "$OUT" | cat -A)";
  echo "### RAW LINE (od -c): $(printf '%s' "$OUT" | od -c | head -5 | tr '\n' '~')";
  echo "### BYTES_HEX: $(printf '%s' "$OUT" | od -An -tx1 | tr -s ' ' | tr '\n' ' ')";
  echo "### EXPECTED (from PRODUCT.md): >>>${EXP}<<<";
  echo "### EXPECTED BYTES_HEX: $(printf '%s' "$EXP" | od -An -tx1 | tr -s ' ' | tr '\n' ' ')";
  # strict byte compare: whole line incl trailing newline vs expected + \n
  if cmp -s <(sed -n "${N}p" "$APP") <(printf '%s\n' "$EXP"); then
    echo "### STRICT_CMP(incl newline): IDENTICAL";
    echo "### VERDICT: PASS"
  else
    echo "### STRICT_CMP(incl newline): DIFFERENT";
    echo "### cmp -l diff:"; cmp -l <(sed -n "${N}p" "$APP") <(printf '%s\n' "$EXP"); echo "cmp exit=$?";
    echo "### VERDICT: FAIL"
  fi
  echo "### END_LOCAL: $(date '+%Y-%m-%d %H:%M:%S %Z')";
  echo;
  } >> "$RAW"
}
{ echo "==============================================================";
  echo "### STEP 3: per-scenario line reads + strict byte comparison";
  echo "### FILE_AT_TEST_TIME: $(ls -l dist/app.txt)"; echo; } >> "$RAW"
run_ac 1 'tool-cli 1' 'AC-001-1'
run_ac 2 'commands=greet,count,export' 'AC-002-1'
run_ac 3 'greet-shout=yes' 'AC-003-1'
sed -n '/STEP 3/,$p' "$RAW"

cd /tmp/orchestra-03/micro2/micro-groups && RAW=docs/changes/tool-cli/verify-5d3765e-r1/acc-g5b-1-raw.txt
{ echo "==============================================================";
  echo "### STEP 4: reproducibility re-run of the documented precondition (bash prepare.sh)";
  echo "### NOTE: AC verdicts above are based on STEP 1..3 single run; this step only checks stability.";
  echo "### CMD: bash prepare.sh   (2nd time)";
  echo "### START_LOCAL: $(date '+%Y-%m-%d %H:%M:%S %Z')";
  echo "### SHA256_BEFORE: $(sha256sum dist/app.txt)";
} >> "$RAW"
S=$(date +%s.%N); bash prepare.sh > /tmp/p2o.txt 2>/tmp/p2e.txt; RC=$?; E=$(date +%s.%N)
{ echo "### EXIT_CODE: $RC";
  echo "### DURATION_S: $(awk -v s=$S -v e=$E 'BEGIN{printf "%.2f", e-s}')";
  echo "### END_LOCAL: $(date '+%Y-%m-%d %H:%M:%S %Z')";
  echo "### STDOUT: $(cat /tmp/p2o.txt)";
  echo "### STDERR: $(cat /tmp/p2e.txt)";
  echo "### SHA256_AFTER: $(sha256sum dist/app.txt)";
  echo "--- sed -n '1,4p' dist/app.txt | cat -A ---";
  sed -n '1,4p' dist/app.txt | cat -A;
  echo "### END STEP 4"; echo;
} >> "$RAW"
{ echo "==============================================================";
  echo "### STEP 5: repo cleanliness (read-only check)";
  echo "### CMD: git rev-parse HEAD; git status --porcelain; git check-ignore -v dist/app.txt";
  echo "### AT: $(date -u +%Y-%m-%dT%H:%M:%SZ)";
  echo "--- git rev-parse HEAD ---"; git rev-parse HEAD;
  echo "--- git status --porcelain ---"; git status --porcelain;
  echo "--- git check-ignore -v dist/app.txt ---"; git check-ignore -v dist/app.txt; echo "check-ignore exit=$?";
  echo "### END STEP 5";
} >> "$RAW"
sed -n '/STEP 4/,$p' "$RAW"
